    queue = [start]
    step = 0

    while queue:
        next_queue = []
        for city in queue:
            if city == end:
                return step

            for neighbor in graph[city]:
                if neighbor not in visited:
                    next_queue.append(neighbor)
                    visited.add(neighbor)
