from math import ceil

def min_energy(x, positions, times, energy_cost):
    barriers = []
    curves = []

    positions.sort()

    for pos in positions:
        barriers.append((pos, pos))

    for time, tl, tr, left, right in times:
        barriers.append((tl, time))
        barriers.append((time, tr))
        curves.append((time, right))

    barriers += [(right, ceil(x + 1))]
    logs = []
    delta = 0
    on_intervals = 0
    min_cost = [0]

    for time, pos in reversed(curves):
        left, right = find_left_right_leap(pos, barriers, min_time=time)

        if len(left) < len(right):
            delta += right * len(right)
            delta -= left
            min_cost.append(ceil(delta))

            if right:
                for right_interval in left:
                    on_intervals += 1

            curr_index = bisect_left(positions, pos)

            if curr_index == len(positions):
                on_intervals -= len(right)
            else:
                on_intervals -= right[curr_index]

            curr_pos = positions[curr_index]

            if curr_pos == min_cost[-1]:
                delta = ceil(min_cost[-1] - curr_pos)
                continue

            delta = ceil(min_cost[-1] - curr_pos)

        elif len(left):
            delta += left * len(left)

            if len(left) < len(right):
                delta += len(right) * on_intervals
                min_cost.append(max(min_cost[-1] - on_intervals, curr_pos))
            else:
                min_cost.append(max(min_cost[-1], curr_pos))

            delta -= len(left)
            on_intervals -= len(left)

        else:
            on_intervals -= len(right)

        delta += ceil(delta)
        min_cost.append(delta)

    return min_cost.pop()

def find_left_right_leap(x, barriers, min_time):
    i = bisect_left(barriers, (min_time, -1))

    if i >= len(barriers):
        return [], len(barriers)

    left = []
    right = []

    for barrier in barriers[i:]:
        left.append(barrier[0] - barrier[1])
        right.append(barrier[0] - barrier[1])

    norm_left = bisect_left(left, x - barrier[1])

    return left[norm_left:], max(ceil(left[norm_left - 1]), -1) * i
