from collections import defaultdict
from typing import List, Tuple

def findResourceBetween(u: int, v: int, roads: List[Tuple[int, int]]) -> int:
    parent = [i for i in range(len(roads) + 1)]
    rank = [1] * (len(roads) + 1)

    def find(x: int) -> int:
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x: int, y: int) -> None:
        x, y = find(x), find(y)
        if x == y:
            return
        if rank[x] > rank[y]:
            parent[y] = x
        else:
            parent[x] = y
            if rank[x] == rank[y]:
                rank[y] += 1

    for x, y in roads:
        union(x, y)

    distance = {}
    level = defaultdict(int)
    for start in range(len(roads) + 1):
        if parent[start] not in distance:
            distance[parent[start]] = 0
        else:
            distance[parent[start]] += 1
        level[parent[start]] = 0

    def bfs(start: int) -> None:
        queue = [start]
        done = set()
        while queue:
            current = queue.pop(0)
            for neighbor in roads:
                if neighbor[0] == current or neighbor[1] == current:
                    if not any(find(i) == current for i in done):
                        distance[neighbor[0]] += distance[neighbor[1]] + 1
                        distance[neighbor[1]] += distance[neighbor[0]] + 1
                        level[neighbor[0]] = level[neighbor[1]] + 1
                        queue.append(neighbor[0])
                        done.add(neighbor[0])
                        queue.append(neighbor[1])
                        done.add(neighbor[1])

    for i in range(len(distance)):
        if find(i) != i:
            bfs(i)
            break

    if u == v:
        return v

    ancestor = find(v)
    ans = {
        ancestor: u,
        v: ancestor
    }
    i = level[ancestor]
    while i != level[v]:
        if ans[find(ancestor)] == ancestor:
            ancestor = ans[find(ancestor)]
        else:
            ans[find(ans[ancestor])] = find(v)
            ancestor = ans[find(ancestor)]
        i -= 1
    return ans[find(v)]

def query(u: int, v: int, c1: int, c2: int, roads: List[Tuple[int, int]]) -> int:
    left, right = c1, c2
    a, b, res = u, v, -1
    if a < left or a > right or left < b or b > right:
        return res
    else:
        ans = {}
        while right >= left:
            x, y = findResourceBetween(left, right, roads)
            if x == left or x == right:
                if x in ans:
                    ans[x] += 1
                else:
                    ans[x] = 1
            else:
                res = x
                break
            right -= 1
    if res != -1:
        ans[res] += 1
        ans[v - 1] -= 1
    res = max(ans.values())
    if res % 2 == 0:
        return -1
    else:
        return min(ans, key=ans.get) + 1

