def is_beautiful(permutation, k):
    from collections import Counter

    # Count the occurrences of each element
    elem_counts = Counter(permutation)

    # Check the parity counts
    if all(ev % 2 == permutation[0] % 2 for e, ev in elem_counts.items()):
        return min(sum(counts // 2) for counts in elem_counts.values()) <= k

def count_beautiful_permutations(n, k, remembered_permutation):
    MOD = 10**9 + 7
    total_count = 1

    used_indices = 0
    memo = {}

    def backtrack(start, unused_positions):
        if used_indices == len(remembered_permutation):
            return 1

        if (start, used_indices, tuple(permutations)) in memo:
            return memo[(start, used_indices, tuple(permutations))]

        permutations = set()
        for position in range(n):
            if position in unused_positions:
                first_e, rest_counts = permutations.pop_or_add_value(remembered_permutation[start])
                rest_counts[position] += 1
                if start != len(remembered_permutation) - 1:
                    permutations.add(first_e, remembered_permutation[start + 1:])
            else:
                continue
            if not unused_positions or start != 0:
                permutations.add(first_e)
            unused_positions.remove(position)
            used_indices += 1

            total_count = (total_count + backtrack(start + 1, unused_positions)) % MOD

            # If the first position is used and k equals 1, add 1
            if k == 1 and used_indices == 1 and start != 0:
                if not permutations or all(counts == 0 for e, counts in permutations):
                    if start != len(remembered_permutation) - 1:
                        permutations.add(-1)
                        unused_positions.add(position)
                    else:
                        unused_positions.remove(position)
                    used_indices -= 1
                    break

        return total_count

    return backtrack(0, itertools.count(1, 1))

