from collections import deque, defaultdict
from itertools import permutations

def valid_mausoleum(heights, signs):
    n = len(heights)
    stack = []
    for sign in signs:
        x, y = sign.split(' ')
        y = int(y) - 1
        if n < y or stack and stack[-1] < heights[y]:
            return False
        elif x == '<' and stack:
            stack.pop()
        elif x == '>' and stack and stack[-1] > heights[y]:
            return False
        if stack and n < y - 1 or stack[-1] > heights[y - 1]:
            if x == '>' and stack[-1] != heights[y - 1]:
                return False
            stack.append('###')
        else:
            stack.append('##')
    return True

n, k = map(int, input().split())

heights = [int(input()) for _ in range(2 * n)]
# Limit the maximum size of the deque for efficiency
heights = heights[:7] + [0] * 28

changes = defaultdict(list)
for _ in range(k):
    x, sign, y = input().split()
    changes[int(y) - 1].append((int(x) - 1, sign, int(y) - 1))

# Function to check if the tower respects additional rules
def respects_special_rules(current_heights, expansions):
    current_heights = deque(current_heights)
    # Get every floor, ignore walls at the top/back
    for level in range(-1, -len(expansions), -1):
        current = max(x for x in current_heights[index + level] for index in [0, 1] if x != 0)
        if current < (n + 1 - level) and level != -1:
            return False
        current_heights[index + level] = 0
    return True

def compute_area():
    results = []
    for perm in permutations(heights, len(heights)):
        if valid_mausoleum(perm, changes):
            results.append(list(perm))
        for i in range(len(perm)):
            if perm[i] == 0:
                index = (i + len(changes[i])) % (2 * n)
                for sign, y in changes[index]:
                    changes[index].remove((sign, y))
                    current_heights = list(perm)
                    current_heights[index] = '##' if sign == '>' and current_heights[index] != '###' else '###'
                    if respects_special_rules(current_heights, changes):
                        results.append(list(perm))
                        changes[index].append((sign, y))
    return results

