from collections import deque

def is_valid(x, y, w, h):
    return 0 <= x < w and 0 <= y < h

def propagate_tail(x, y, tail):
    if x + 1 == tail[0] or y + 1 == tail.get(0, y):
        tail[0] = x
        tail[1] = y + 1
    if x - 1 == tail[0] or y + 1 == tail.get(0, y):
        tail[0] = x - 1
        tail[1] = y + 1
    if x + 1 == tail[0] or y - 1 == tail.get(0, y):
        tail[0] = x
        tail[1] = y - 1
    if x - 1 == tail[0] or y - 1 == tail.get(0, y):
        tail[0] = x - 1
        tail[1] = y - 1

def shortest_path(N, M, w, h, m, tail, supply_start):
    queue = deque()
    directions = {'N': (0, -1), 'S': (0, 1), 'E': (1, 0), 'W': (-1, 0)}
    delta = {(0, 0): 0}
    queue.append((0, m, m))
    while queue:
        day, ship_x, ship_y = queue.popleft()
        if is_valid(ship_x, ship_y, h, w) and supply_start[ship_x][ship_y] < day:
            supply_start[ship_x][ship_y] = day + 1
        if is_valid(ship_x, ship_y, h, w) and supply_start[ship_x][ship_y] > day:
            continue
        for d in directions:
            new_x, new_y = ship_x + directions[d][0], ship_y + directions[d][1]
            if (new_x, new_y) == (tail[0], tail[1]):
                continue
            mask = (1 << d) - 1
            if (x := supply_start[new_x][new_y]) - day > mask:
                continue
            delta[x] = day
            if tail and mask & tail:
                delta[x | mask] = day + 1
            if delta.get(x | mask, float('inf')) > delta.get(x, float('inf')) + 1:
                delta[x | mask] = delta[x] + 1
            queue.append((delta[x | mask] + min((supply_start[new_x][new_y]: set({d[1]}), 8)), x | delta[x], new_y))

    for d in directions:
        new_x, new_y = w - 1, h - 1
        if (y := supply_start[new_x][new_y]) - day > 1:
            continue
        delta[x] = day
        if delta.get(x, float('inf')) > day + 1:
            delta[x] = day + 1
        queue.append((delta.__len__() + min((supply_start[new_x][new_y]),
                                           delta.get(x, float('inf') + 1)), 1 << (mask := d), y))

    return min((delta == float('inf') and delta[-1:] or -1 for delta in delta.values()), abs)

