from functools import cache

MOD = 998244353

def count_permutations(n, k, values):
    @cache
    def dp(i, last, minv):
        if i == n:
            return 1
        cnt = 0
        for j in range(i, n):
            if values[j] == -1:
                continue
            if j + 1 != last and values[i] > values[j]:
                minv = min(minv, values[j])
                cnt = (cnt + dp(j + 1, i, minv) * factorial(n - n + j - i)) % MOD
            elif j > last:
                cnt = (cnt + dp(j + 1, j, values[i])) % MOD
        return cnt

    initial = 0 if values[0] == -1 else dp(1, 0, values[0])
    return (initial * factorial(n + k - initial)) % MOD

