    start_points = [segment[0] for segment in segments]
    end_points = [segment[1] for segment in segments]

    # Sort start and end points
    start_points.sort()
    end_points.sort()

    # Build a prefix sum array of the start points
    prefix_sum_start = [0]
    for point in start_points:
        prefix_sum_start.append(prefix_sum_start[-1] + 1)

    # Build a suffix sum array of the end points
    suffix_sum_end = [0]
    for point in end_points[::-1]:
        suffix_sum_end.append(suffix_sum_end[-1] + 1)
    suffix_sum_end = suffix_sum_end[::-1]

