def permute(n, k, v):
    if k == 0:
        return 1
    k %= (n-1)
    c, d = 0, 0
    for i in range(n):
        if i > 0 and v[i] < v[i-1]:
            c += 1
        if i + k >= n or (i >= k and v[i+1] < v[i-k]):
            d += 1
    ans = 1
    lo = c
    hi = (k-1)//(n-k) + 1

    while lo <= hi:
        mid = (lo + hi) // 2
        c1 = mid
        d1 = 0
        for i in range(n):
            if i < min(n, n-(k-1)-1) and v[i] < v[i-1]:
                c1 += 1
            if i >= mid and v[i+1] < v[i-mid]:
                d1 += 1
            if c1 <= d1:
                ans *= c1
                ans %= mod
                d1 += c1
                c1 = 0
            else:
                c1 = 0
        if d1 < d:
            lo = mid + 1
        else:
            hi = mid - 1
    return ans * (c+(d-c)//(n-k)) % mod

