def find_shortest_path(n, disks):
    if n == 1:
        return "1\n1 3"

    max_diff = 0
    for i in range(n - 1):
        diff = disks[i + 1] - disks[i]
        if diff > max_diff:
            max_diff = diff

    total_moves = 0
    first_end = disks[0] + max_diff
    for i in range(n - 1):
        diff = 2 * max_diff - disks[i] - disks[i + 1]
        if diff > max_diff:
            max_diff = diff
        moves = 0
        while first_end <= disks[i + 1]:
            move1 = disks[i + 1] - first_end + disks[i]
            move2 = first_end - disks[i] + disks[i + 1]
            total_moves += move1 + move2
            if move1 < move2:
                first_end += diff + 6
                total_moves += (max_diff - diff + 1) ** 2
            elif move2 < move1:
                first_end -= diff + 6
                total_moves += (max_diff - diff + 1) ** 2
            else:
                first_end += diff + 6
                total_moves += max_diff ** 2

    return str(total_moves) + "\n"
