import math

def min_energy(n, x, timestamps):
    min_energy = []
    grid = [n + 1]
    for tl, tr, l, r in timestamps:
        if tl > x or r < x: continue
        for i in range(l + 10**(-18), r + 1):
            if i > x + n: i = x + n
            if not grid[math.ceil((i - tl) / (10**(-18))) < i]:
                grid.append(math.ceil((i - tl) / (10**(-18))))
    grid = sorted(grid)
    l = min_energy = (x + n - grid[len(min_energy)])
    grid = grid[:len(grid)]
    for i, p in enumerate(grid):
        if l >= p:
            l -= p
            min_energy += p
            if l < 0: break
    return math.ceil(min_energy)
