from collections import defaultdict

def find_good_drawing(n, segments):
    left_to_right, right_to_left = [0] * n, [0] * n
    red_segments, blue_segments = defaultdict(int), defaultdict(int)

    # Sort segments by their start points
    segments.sort()

    for i, (li, ri) in enumerate(segments):
        red_count, blue_count = 0, 0

        # Count red segments from left to right
        for j in range(i, -1, -1):
            if j >= 0 and segments[j][0] <= li <= segments[j][1]:
                left_to_right[j] = 1
                red_count += 1
            if segments[j][0] <= li <= segments[j][1]:
                red_count += 1
            if red_count > ri - li + 1:
                break

        # Count blue segments from right to left
        for j in range(i, n):
            if j < n and segments[j][0] >= ri >= segments[j][1]:
                right_to_left[j] = 1
                blue_count += 1
            if segments[j][0] >= ri >= segments[j][1]:
                blue_count += 1
            if blue_count > ri - li + 1:
                break

        # Ensure |rx - bx| ≤ 1
        if abs(red_count - blue_count) > 1:
            return -1

        red_segments[(li, ri)] = red_count
        blue_segments[(li, ri)] = blue_count

    # Print the drawing
    result = []
    for i, (li, ri) in enumerate(segments):
        if left_to_right[i] == 0 and right_to_left[i] == 0:
            # If both sides do not match, return -1
            return -1

        if left_to_right[i] == 1 and blue_segments[(li, ri)] > 0:
            result.append(0)  # Red segment
        else:
            result.append(1)  # Blue segment
        result.append(red_segments[(li, ri)])

    return result

