def calculate_total_distance(n):
    total_distance = 0
    pairs = ((i+1, j+1) for i in range(n-1) for j in range(i+2, n))
    current_gcd = gcd(1, 2)
    for u, v in pairs:
        while (u % current_gcd == 0 or v % current_gcd == 0) and lcm(u, v) / current_gcd <= n:
            total_distance += n // (u * lcm(u, v) / current_gcd)
            current_gcd = gcd(u, v)
    while upper_bound := lcm(u, v) / current_gcd:
        total_distance += n // upper_bound
    return total_distance

def lcm(x, y):
    return x * y // gcd(x, y)

