        miss_left = miss_right = True
        step_seq = [0 for _ in range(max(len(steps_sequence)+5, i))]
        while i not in step_seq:
            if step_seq[i] in step:
                step_seq[i] = step_seq[2*i+1] = '2' if i%2 == 0 else 'O'
                miss_left = False
            step_seq = step_seq[1:i+2]
            i = max(i-2, 0)
        return miss_left and miss_right

    max_proportion = 0.0
    steps = list(steps_sequence)
    max_long = len(steps) - max(steps.count('L'),steps.count('R')) + abs(steps.count('X')-max(steps.count('L'),steps.count('R'))) - 1
    for c in range(max_long//2):
        for index in range(0, max_long):
            if steps[index] == 'L' and c%2:
