def bfs(start, end, city_map):
    visited = {start: 0}
    queue = [(start, 0)]

    while queue:
        vertex, count = queue.pop(0)
        for neighbor in city_map[vertex]:
            if neighbor not in visited or count > visited[neighbor]:
                visited[neighbor] = count + 1
                queue.append((neighbor, count + 1))

    return visited.get(end, -1)

def solve(input_data):
    n, cities, roads, buses, bus_routes = input_data

    city_map = {city: set() for city in cities}
    edge_map = defaultdict(list)
    for road in roads:
        edge_map[road-1].append(cities.index(road))
        city_map[road-1].add(roads.index(road))

    for _, b in bus_routes:
        edge_map[b-1].append(cities.index(b))
        city_map[b-1].add(buses.index(b))

