def correct_letter(word, index):
    word = list(word)
    if word[index] in dictionary:
        return ''.join(word)
    if index > 0 and word[index-1] != ' ':
        return word[:index] + ' ' + word[index] + correct_letter(word, index+1)
    if index < len(word) - 1 and word[index+1] != ' ':
        return word[:index+1] + correct_letter(word, index+1)
    return word

# Function to correct a word with multiple mistakes
def correct_word(word):
    word = list(word)
    for i in range(len(word)):
        corrected_word = correct_letter(word, i)
        if corrected_word == word:
            break
        word = corrected_word
    return ''.join(word)

