def min_steps(sequence):
    steps_left = len(sequence)
    right_steps = 0
    max_right_steps = 0

    for i in range(len(sequence)):
        if sequence[i] == "R":
            right_steps += 1
            if right_steps < max_right_steps:
                right_steps = 0
                max_right_steps = 1
            else:
                max_right_steps += 1
        else:
            max_right_steps -= 1

    return min(steps_left, right_steps)

def optimal_steps_multiplier(steps1, steps2):
    if steps1 == "X" or steps2 == "X":
        return 1
    steps_multiplier = 1
    while steps1 != "" and steps2 != "":
        if min(steps1, steps2) == steps1:
            diff = int((ord(steps1[-1].lower()) - ord("a")) / 5)
            steps1 = steps1[:-1].replace(diff, "", 1)
            steps2 = steps2[diff:]
        else:
            diff = int((ord(steps2[-1].lower()) - ord("a")) / 5)
            steps2 = steps2[:-1].replace(diff, "", 1)
            steps1 = steps1[diff:]
        steps_multiplier += 1
    return min(steps1, steps2) ** steps_multiplier

