from math import factorial

def count_ways(n, k, heights):
    block_count = 2*n
    allowed_heights = set()

    for i in range(k):
        x, sign, y = [int(height) for height in input().split(" ")]
        if sign == '=':
            allowed_heights.add(y)
        elif sign == '>':
            if y < block_count:
                allowed_heights.add(y)
        elif sign == '<':
            if y >= 0:
                allowed_heights.add(y)
        elif sign == '>=':
            if y < block_count:
                allowed_heights.add(y)
        elif sign == '<=':
            if y == block_count - 1:
                allowed_heights.add(y)

    ways = 1
    for height in sorted(allowed_heights):
        ways *= factorial(block_count - 1) // (factorial(height - 1) * factorial(block_count - height - 1))

    return ways

